local picker = require("neo-gitmoji.gitmoji-picker").open_gitmoji_picker
local Git = require("neo-gitmoji.git-commands")
local floating_input = require("neo-gitmoji.floating-input")

local M = {}

function M.setup()
  local config = require("neo-gitmoji.commands-and-keymaps")
  config.set_commands()
  config.set_keymaps()
end

function M.open_floating()
  picker(function(value)
    floating_input.create_floating_buffer({
      title = "Enter the commit title: [" .. value.emoji .. " " .. value.description .. "]",
      on_confirmation_callback = function(a_title, close, show_error)
        local full_title = value.emoji .. " " .. a_title
        Git.commit(
          full_title,
          function()
            vim.notify("Committed: " .. full_title, vim.log.levels.INFO)
            close()
          end,
          function(err)
            vim.notify(err, vim.log.levels.ERROR)
            show_error(err)
          end
        )
      end,
    })
  end)
end

return M

local start_neo_gitmoji = require("neo-gitmoji").open_floating

local M = {}

function M.set_commands()
  vim.api.nvim_create_user_command("NeoGitmoji", function() start_neo_gitmoji() end, {})
end

function M.set_keymaps()
  vim.keymap.set("n", "<leader>gm", function() start_neo_gitmoji() end, {
    desc = "Gitmoji",
  })
end

return M

local Git = {}

function format_title(title)
  return title:gsub("`", "\\`")
end

function Git.commit(title, on_success, on_failure)
  local output = {}

  vim.fn.jobstart({ "git", "commit", "-m", title }, {
    on_stdout = function(_, data)
      for _, line in ipairs(data) do
        if line ~= "" then
          table.insert(output, line)
        end
      end
    end,
    on_stderr = function(_, data)
      for _, line in ipairs(data) do
        if line ~= "" then
          table.insert(output, line)
        end
      end
    end,
    on_exit = vim.schedule_wrap(function(_, exit_code)
      if exit_code == 0 then
        on_success()
      else
        on_failure(table.concat(output, "\n"))
      end
    end),
  })
end

return Git
